    mockUseAdminStore.mockReturnValue({ ovrFor: () => [], updateStaff, sendLink });
    const { ReactivateModal } = await import("@/components/admin/enroll/LifecycleModals");
    render(<ReactivateModal user={{ ...STAFF_MEMBER, status: "DEACTIVATED" } as never} onClose={vi.fn()} />);
    fireEvent.click(screen.getByRole("button", { name: /reactivate account/i }));
    expect(updateStaff).toHaveBeenCalledWith("u1", expect.objectContaining({ status: "ACTIVE" }));
